const preventContextMenu = (e) => {
        e.addEventListener("contextmenu", (e) => e.preventDefault());
    },
    createYouTubeIframe = (e, t) => {
        let a = document.createElement("iframe");
        return (
            (a.className = t),
            (a.src = `https://www.youtube-nocookie.com/embed/${e}?autoplay=1&rel=0&modestbranding=1&controls=1&fs=0`),
            (a.allow = "autoplay; encrypted-media"),
            (a.allowFullscreen = !1),
            (a.referrerPolicy = "strict-origin"),
            a
        );
    },
    initLocalVideos = () => {
        document.querySelectorAll("[data-lv]").forEach((e) => {
            let t = e.querySelector(".lv-video"),
                a = e.querySelector(".lv-play-btn"),
                r = () => e.classList.remove("playing");
            a.addEventListener("click", () => {
                t.play(), e.classList.add("playing");
            }),
                t.addEventListener("pause", r),
                t.addEventListener("ended", r),
                preventContextMenu(t);
        });
    },
    initYouTube = ({
        wrapperSelector: e,
        buttonSelector: t,
        iframeClass: a,
        dataAttribute: r,
    }) => {
        document.querySelectorAll(e).forEach((e) => {
            let l = e.querySelector(t),
                n = e.dataset[r];
            l.addEventListener("click", () => {
                if (e.classList.contains("playing")) return;
                let t = createYouTubeIframe(n, a);
                (e.innerHTML = ""),
                    e.appendChild(t),
                    e.classList.add("playing");
            }),
                preventContextMenu(e);
        });
    };
initLocalVideos(),
    initYouTube({
        wrapperSelector: "[data-yt-id]",
        buttonSelector: ".yt-play-btn",
        iframeClass: "yt-iframe",
        dataAttribute: "ytId",
    }),
    initYouTube({
        wrapperSelector: "[data-ytg-id]",
        buttonSelector: ".ytg-play-btn",
        iframeClass: "ytg-iframe",
        dataAttribute: "ytgId",
    });
